/* ANIM:END */
const rigCache = new Map();
const rigPath = ly => { let P = rigCache.get(ly); if (!P) { P = new Path2D(); for (const q of ly.p) { P.moveTo(q[0], q[1]); for (let i = 2; i < q.length; i += 2) P.lineTo(q[i], q[i + 1]); P.closePath(); } rigCache.set(ly, P); } return P; };
const rigPathD = ly => { let P = rigCache.get(ly); if (!P) { P = new Path2D(); for (const q of ly.p) { let x = q[0], y = q[1]; P.moveTo(x, y); for (let i = 2; i < q.length; i += 2) P.lineTo(x += q[i], y += q[i + 1]); P.closePath(); } rigCache.set(ly, P); } return P; };   // (points stored as steps)
function rigLayers(c, R, L, path = rigPath){ c.lineJoin = 'round'; c.lineWidth = R.sw || 1; const rule = R.rule || 'evenodd'; for (const ly of L) { const P = path(ly); c.fillStyle = c.strokeStyle = ly.c < 0 ? R.line : R.pal[ly.c]; c.fill(P, rule); if (ly.c >= 0 && R.sw) c.stroke(P); } }   // (rule 'nonzero' and no stroke: layers stacked by vtracer)
// a braid bent along a curve: each point of the straight braid (u across, v along) goes to the curve at v, u along its normal
function rigBraid(c, R, x0, y0, cx, cy, ex, ey){
  const B = R.braid, len = B.len, at = (tt) => { const u = 1 - tt; return [u * u * x0 + 2 * u * tt * cx + tt * tt * ex, u * u * y0 + 2 * u * tt * cy + tt * tt * ey, 2 * u * (cx - x0) + 2 * tt * (ex - cx), 2 * u * (cy - y0) + 2 * tt * (ey - cy)]; };
  rigLayers(c, R, B.l, ly => { const P = new Path2D(); for (const q of ly.p) { for (let i = 0; i < q.length; i += 2) { const [bx, by, tx, ty] = at(clamp(q[i + 1] / len, 0, 1.05)), m = Math.hypot(tx, ty) || 1, X = bx + ty / m * q[i], Y = by - tx / m * q[i]; i ? P.lineTo(X, Y) : P.moveTo(X, Y); } P.closePath(); } return P; });
}
function rigDraw(c, p, t){
  const R = tracedOK(p.look, 'hojas') && RIG[VEC_LOOK[p.look]]; if (!R) return false;
  const q8 = facing8(p), flip = q8 >= 5, vi = flip ? 8 - q8 : q8, view = VEC_VIEW[vi], V = R.views[view], L = LOOKS[p.look]; if (!V) return false;
  const d = vi === 0 || vi === 1 ? 0 : vi === 2 ? 1 : 2, fl = braidFlick(p, t, d), side = vi === 2;
  const w = p.moving ? Math.sin(p.walk * TAU) : 0, bob = p.moving ? -Math.abs(w) * 12 : Math.sin(t * 2 + p.x) * 2.5;
  const run = clamp(((p._spd || 0) - 34) / 46, 0, 1), out = run * 1.05, b2 = Math.sin(p.walk * TAU), wind = Math.sin(t * 1.3) * .6 + Math.sin(t * 3.1) * .3;
  if (!p.noShadow) ell(c, p.x, p.y, 11 * L.h, 4, 'rgba(30,40,20,.26)');
  c.save(); c.translate(p.x, p.y); const k = L.h * .1; c.scale(k * (flip ? -1 : 1), k);
  // the feet: up and down (from the front or behind), forward and back (from the side)
  const fb = vi === 0 || vi === 4, lift = [Math.max(0, w), Math.max(0, -w)];
  ['footL', 'footR'].forEach((f, i) => { c.save(); if (fb) c.translate(0, -lift[i] * 26); else c.translate((i ? -w : w) * 28, -lift[i] * 14); rigLayers(c, R, V[f]); c.restore(); });
  c.translate(0, bob);
  const arm = R.arm[fb ? 'frente' : 'lado'], hand = fl >= 0 ? flickHand(fl, side).map(v => v * 10.4) : null;
  const drawArm = (i, ang) => { const [sx, sy] = V.sh[i]; c.save(); c.translate(sx, sy); let sq = 1; if (hand && i === 1) { ang = Math.atan2(-(hand[0] - sx), hand[1] - sy); sq = clamp(Math.hypot(hand[0] - sx, hand[1] - sy) / arm.len, .45, 1); } c.rotate(ang); c.scale(1, sq); /* (reaching up: the arm shortened, as if bent) */ if (fb && i === 0) c.scale(-1, 1); rigLayers(c, R, arm.l); c.restore(); };
  const swing = p.moving ? w * .35 : Math.sin(t * 1.1 + p.x) * .03;
  const braid = (i, th, behind) => {   // (from its root, hanging with the angle the run gives it; or held, or thrown back)
    const [x0, y0] = V.br[i], len = R.braid.len, sn = Math.sin(th), cs = Math.cos(th), sway = (wind + (p.moving ? w : 0)) * 14 * Math.max(.2, cs);
    if (fl >= 0 && i === (side ? 0 : 1) && fl < .62) { const [hx, hy] = hand; rigBraid(c, R, x0, y0, (x0 + hx) / 2 + 20, (y0 + hy) / 2 + 30, hx, hy); return; }
    const ex = x0 + sn * len + sway, ey = y0 + cs * len; rigBraid(c, R, x0, y0, x0 + sn * len * .5, y0 + cs * len * .5 + Math.abs(sn) * len * .22, ex, ey);
  };
  const flung = fl >= .62 ? (fl - .62) / .38 : -1, thL = -out * (1 + .25 * b2), thR = out * (1 - .25 * b2);
  const thFl = flung >= 0 ? (side ? -1 : 1) * lerp(1.62, .9, flung * flung) : null;
  if (!fb) drawArm(0, -swing);                                    // (the far arm, behind)
  if (side) braid(0, thFl ?? -(out * (1.1 + .3 * Math.sin(p.walk * TAU * 2))) - .1);   // (from the side the braid hangs behind the head)
  else if (p.braidBack && fl < 0 && vi >= 3) braid(1, thR);     // (thrown back: behind her)
  rigLayers(c, R, V.torso);
  // the face as it was drawn; over it, only when needed: the eyes closed (blinking), the mouth open (talking)
  const MK = R.marks?.[view];
  if (MK) {
    const fill = (x, y, rx, ry, col) => { c.beginPath(); c.ellipse(x, y, rx, ry, 0, 0, TAU); c.fillStyle = col; c.fill(); };
    if (p.blink > 0) for (const [x, y, rx, ry] of MK.eyes) {
      fill(x, y, rx, ry, R.pal[3]);
      c.strokeStyle = R.line; c.lineWidth = Math.max(4, ry * .22); c.lineCap = 'round'; c.beginPath(); c.moveTo(x - rx * .8, y); c.quadraticCurveTo(x, y + ry * .55, x + rx * .8, y); c.stroke();
    }
    if (isTalking(p) && MK.mouth) {
      let [x, y, rx, ry] = MK.mouth; const o = .45 + Math.abs(Math.sin(t * 13)) * .55;
      if (side) { x -= rx * .4; rx *= .55; ry = Math.min(ry, 6); }   // (in profile: the lips at the edge of the face, opening a little)
      fill(x, y, rx + 3, ry + 3, R.pal[3]); fill(x, y + 2, rx * .8, (ry + 8) * o, '#9a3a32'); fill(x, y + 2 + (ry + 8) * o * .45, rx * .5, (ry + 8) * o * .45, '#e07a70');
    }
  }
  if (fb) drawArm(0, swing);
  if (!side) { braid(0, thL); if (!(p.braidBack && fl < 0 && vi >= 3) || vi < 3) braid(1, thFl ?? thR); }
  drawArm(1, fl >= 0 ? 0 : -swing);
  if (L.hat && R.hat[view]) { const [hx, hy] = V.hat; c.save(); c.translate(hx, hy); if (p.askew) c.rotate(-.32); rigLayers(c, R, R.hat[view].l); c.restore(); }
  c.restore(); return true;
}